        uint plan_id;
        uint inspector_id;
        uint256 start_date;
        uint256 end_date;
        bool can_harvest;
        string evaluated_result;
        string[] images;
    }

    struct Order {
        uint id;
        uint retailer_id;
        uint plan_id;
        uint packaging_type_id;
        uint deposit_price;
        string status;
        uint estimated_pickup_date;
    }

    struct Transaction {
        uint id;
        uint order_id;
        uint price;
        string status;
        uint256 payment_date;
    }

    struct PackagingProduct {
        uint id;
        uint packaging_task_id;
        uint harvesting_task_id;
        uint order_id;
        uint packaging_quantity;
        string qr_code;
        string status;
    }

    event InspectionCreated(uint indexed id, uint plan_id);
